{
  "case_id": "C06",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "The headline result",
      "narration": "Can gut bacteria keep you lean? In this experiment, germ-free mice - raised with no gut microbes at all - were given the gut community of either a lean or an obese donor mouse. Eight weeks later, the lean-donor group had gained twenty-four percent less fat.",
      "on_screen": "Two mouse silhouettes, lean donor and obese donor, arrows into germ-free recipients; big number '-24% fat mass (p = 0.003, n = 20 per group)'",
      "claim_refs": ["SYN-C06:Abstract", "SYN-C06:Results (main text, donor pair 1)"]
    },
    {
      "beat": "One pair out of four",
      "narration": "But that number comes from a single donor pair. The study used four. The other three sit in the supplement: minus six percent, plus three, minus nineteen. Pooled together, the effect shrinks to about eleven percent, with a range that still includes no effect at all.",
      "on_screen": "Four-point forest plot: -24%, -6%, +3%, -19%; pooled diamond at -11% with 95% CI -23% to +1% crossing the zero line",
      "claim_refs": ["SYN-C06:Supplementary Table S3", "SYN-C06:Methods (main text uses donor pair 1)"]
    },
    {
      "beat": "The buried control",
      "narration": "A second control buried in the supplement matters even more. When both groups were fed the same amount of food, the difference in fat almost vanished - four percent, not statistically meaningful. So much of the original effect looks like how much the mice ate, not what was living in their guts.",
      "on_screen": "Side-by-side bars: free-feeding -24% versus pair-fed -4% (p = 0.55); food bowls equalised with a label 'same intake'",
      "claim_refs": ["SYN-C06:Supplementary Figure S2"]
    },
    {
      "beat": "What to take away",
      "narration": "None of this proves gut microbes are irrelevant to body fat. It shows this study does not settle it - and that when a striking result rests on one comparison out of four, the supplement is where you should look.",
      "on_screen": "Text card: 'Check the supplement' over a faded paper with the main-text figure and the supplementary pages highlighted",
      "claim_refs": ["SYN-C06:Discussion", "SYN-C06:Conclusion", "SYN-C06:Limitations"]
    }
  ]
}
